    resolverAlerta: {
        parameters: {
            query?: never;
            header?: never;
            path: {
                /**
                 * @description Identificador de la alerta (UUID).
                 * @example 3f1d0a4e-0000-4000-8000-000000000001
                 */
                id: string;
            };
            cookie?: never;
        };
        /**
         * @description La nota es obligatoria: es la justificacion auditable de la
         *     decision y viaja al asiento `alerta.resuelta`. En una critica va
         *     ademas la `accion` sobre el dato. Quien resolvio, y con que rol,
         *     sale de la sesion.
         */
        requestBody: {
            content: {
                "application/json": components["schemas"]["ResolucionDeAlerta"];
            };
        };
        responses: {
            /** @description La alerta, ya cerrada y firmada. */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    /**
                     * @example {
                     *       "id": "3f1d0a4e-0000-4000-8000-000000000001",
                     *       "tipo": "reserva_declaracion_incompleta",
                     *       "detalle": "la declaracion vigente de la obra \"obra-12\" suma 60% en 1 parte(s) y no llega a 100",
                     *       "periodo": "2025-01",
                     *       "referencia": "obra:obra-12",
                     *       "ref_tipo": "obra",
                     *       "ref_id": "obra-12",
                     *       "critica": false,
                     *       "detectada": "2026-05-02T08:30:00Z",
                     *       "resuelta": true,
                     *       "resuelta_por": "usr-admin",
                     *       "resuelta_en": "2026-05-03T14:05:00Z",
                     *       "nota": "hablado con la autora, declara esta semana"
                     *     }
                     */
                    "application/json": components["schemas"]["Alerta"];
                };
            };
            /**
             * @description El id no es un UUID, el cuerpo no es un JSON valido, o la nota
             *     falta o esta vacia. Tambien 400 si el pedido no cuadra con la
             *     alerta: una critica sin `accion`, una accion que su tipo no admite,
             *     un campo que la accion no lee, un `uso_id` que no repite el
             *     registro de la alerta, un `reporte_id` con otros bytes o de otro
             *     periodo, un `tipo_obra` fuera de `RD 9.1.1`, o una nota de mas de
             *     300 caracteres en una accion que escribe sobre la fila.
             */
            400: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Error"];
                };
            };
            /** @description Falta el token, o esta caducado o revocado. */
            401: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    /**
                     * @example {
                     *       "error": "sesion invalida o expirada"
                     *     }
                     */
                    "application/json": components["schemas"]["Error"];
                };
            };
            /** @description Autenticado, pero el rol no basta. */
            403: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    /**
                     * @example {
                     *       "error": "no autorizado"
                     *     }
                     */
                    "application/json": components["schemas"]["Error"];
                };
            };
            /** @description No hay ninguna alerta con ese identificador. */
            404: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    /**
                     * @example {
                     *       "error": "esa alerta no existe"
                     *     }
                     */
                    "application/json": components["schemas"]["Error"];
                };
            };
            /**
             * @description La alerta existe y alguien la cerro antes. O la accion ya no
             *     aplica porque el dato cambio desde que se detecto: la fila ya no
             *     pondera, la entrega ya esta excluida, el tipo ya esta puesto, o
             *     excluir dejaria el hecho sin ninguna copia que lo cuente. En ese
             *     caso la alerta sigue abierta: reevaluar el periodo y mirar otra vez.
             */
            409: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Error"];
                };
            };
            /** @description Esta instalacion no cableo la deteccion de anomalias. */
            503: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    /**
                     * @example {
                     *       "error": "la deteccion de anomalias no esta configurada en esta instalacion"
                     *     }
                     */
                    "application/json": components["schemas"]["Error"];
                };
            };
        };
    };
