    avanzarEtapaProceso: {
        parameters: {
            query?: never;
            header?: never;
            path: {
                /** @example proc-caracol-2026-01-1 */
                id: string;
            };
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /** @description El proceso, en su nueva etapa. */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Proceso"];
                };
            };
            /** @description Falta el token, o esta caducado o revocado. */
            401: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    /**
                     * @example {
                     *       "error": "sesion invalida o expirada"
                     *     }
                     */
                    "application/json": components["schemas"]["Error"];
                };
            };
            /** @description Autenticado, pero el rol no basta. */
            403: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    /**
                     * @example {
                     *       "error": "no autorizado"
                     *     }
                     */
                    "application/json": components["schemas"]["Error"];
                };
            };
            /** @description No hay ningun proceso con ese identificador. */
            404: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    /**
                     * @example {
                     *       "error": "ese proceso no existe"
                     *     }
                     */
                    "application/json": components["schemas"]["Error"];
                };
            };
            /**
             * @description El estado del proceso no permite avanzar -por ejemplo, una
             *     compuerta sin las dos firmas de la revision actual, o una etapa
             *     terminal. El cuerpo de la peticion era correcto; lo que no cuadra
             *     es el estado contra `RD 13.5`.
             *
             *     Tambien 409 si otra transicion escribio la fila entre que este
             *     request la leyo y la escribio (control de concurrencia
             *     optimista): releer el proceso y reintentar resuelve esto.
             *
             *     Y 409 si el periodo tiene anomalias criticas sin resolver al
             *     salir de `deducciones`: se resuelven en `/alertas`, corrigiendo
             *     el dato (#164). Las aceptadas tal cual no bloquean; el asiento
             *     `proceso.etapa_avanzada` las cuenta en
             *     `criticas_aceptadas_tal_cual`.
             *
             *     Y 409 si la liquidacion del periodo no deja mover la corrida
             *     (ADR 0024):
             *     - al salir de `liquidacion_final` hacia `pago_registro`: alguna
             *       corrida hermana del mismo periodo todavia no llega a esa etapa
             *       (`ErrLiquidacionEnEspera`).
             *     - al entrar o al salir de `liquidacion_final`: el periodo y
             *       circuito ya se liquidaron sin esta corrida
             *       (`ErrPeriodoYaLiquidado`), o dos corridas listas del periodo
             *       reparten la misma bolsa (`ErrBolsaRepetida`).
             *
             *     El mensaje nombra las corridas implicadas.
             *
             *     Al entrar a `importe_obra`, 409 si la bolsa no tiene usos
             *     identificados de su canal en el periodo: el mensaje nombra la
             *     bolsa, el canal y el periodo, y dice si falta cargar el reporte
             *     del usuario de recaudo, corregir el `canal_id` de sus filas o
             *     identificarlas en la cola, o si todas estan excluidas (`R-27`)
             *     o descartadas y ninguna pondera. Y 409 si el snapshot congelado
             *     al abrir la corrida no trae un parametro que el motor exige
             *     (una corrida abierta antes de que existiera
             *     `cine_teatro.base`): el mensaje nombra la clave, el snapshot no
             *     se vuelve a resolver y hay que abrir una corrida nueva de la
             *     bolsa.
             */
            409: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    /**
                     * @example {
                     *       "error": "avanzar etapa de \"proc-rcn-2026-01-1\": liquidar \"proc-rcn-2026-01-1\": la liquidacion del periodo espera a otras corridas: 2026-01/nacional no se liquida hasta que lleguen a \"liquidacion_final\": proc-caracol-2026-01-1 (verificacion)"
                     *     }
                     */
                    "application/json": components["schemas"]["Error"];
                };
            };
            /**
             * @description Fallo del servidor. Incluye:
             *     - la falta de un `smmlv` vigente en `parametros` al entrar a
             *       `liquidacion_final`: sin el no se evalua `R-11` y la corrida no
             *       avanza (ADR 0004).
             *     - inconsistencias de datos en la liquidacion (`ErrCorridaNoCuadra`
             *       o `ErrInconsistenciaLiquidacion`): totales que no cuadran
             *       (deducciones mayores al bruto o distribuido mayor al neto),
             *       corridas hermanas sin resultados de proceso, corridas en etapas
             *       posteriores sin firmas de verificacion en base de datos, o
             *       disparador ausente entre las corridas del periodo.
             */
            500: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    /**
                     * @example {
                     *       "error": "parametro normativo ausente"
                     *     }
                     */
                    "application/json": components["schemas"]["Error"];
                };
            };
        };
    };
